#!/usr/bin/env python3
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
def rep(path, old, new, count=1):
    text=path.read_text(encoding='utf-8'); n=text.count(old)
    if n < count: raise SystemExit(f'{path}: expected >= {count} match, got {n}')
    path.write_text(text.replace(old,new,count), encoding='utf-8')

p=ROOT/'app/src/main/java/com/rww/wetypeswipe/MainActivity.java'
rep(p,'import android.text.InputFilter;\n', 'import android.text.InputFilter;\nimport android.text.InputType;\n')
rep(p,'    private final String[] qwertyCustomLabels = new String[26];\n', '    private final String[] qwertyCustomLabels = new String[26];\n    private final String[] qwertyInsertTexts = new String[26];\n')
