rep(p,'            case Config.ACTION_SELECT_TO_DOCUMENT_END: return "选文尾";\n', '            case Config.ACTION_SELECT_TO_DOCUMENT_END: return "选文尾";\n            case Config.ACTION_INSERT_TEXT: return "文本";\n')
